package com.habilitesrandom.api;
import net.minecraft.resources.Identifier;import java.util.*;
public final class AbilityBuilder {private final Identifier id;private String name="",description="",particle="",sound="";private int cooldown,duration;private double damage,range,area,horizontal,vertical;private Set<AbilityType> types=Set.of();private AreaShape shape=AreaShape.NONE;private List<EffectSpec> effects=List.of();private BlockInteraction blocks=BlockInteraction.NONE;private boolean entities=true,players=true;private AbilityDefinition.ProjectileSpec projectile=AbilityDefinition.ProjectileSpec.NONE;private AbilityDefinition.DestructionSpec destruction=AbilityDefinition.DestructionSpec.NONE;
 AbilityBuilder(Identifier id){this.id=Objects.requireNonNull(id);}public AbilityBuilder displayName(String v){name=v;return this;}public AbilityBuilder description(String v){description=v;return this;}public AbilityBuilder cooldownTicks(int v){cooldown=v;return this;}public AbilityBuilder damage(double v){damage=v;return this;}public AbilityBuilder range(double v){range=v;return this;}public AbilityBuilder area(AreaShape s,double v){shape=s;area=v;return this;}public AbilityBuilder durationTicks(int v){duration=v;return this;}public AbilityBuilder types(AbilityType...v){types=Set.of(v);return this;}public AbilityBuilder effects(EffectSpec...v){effects=List.of(v);return this;}public AbilityBuilder presentation(String p,String s){particle=p;sound=s;return this;}public AbilityBuilder knockback(double h,double v){horizontal=h;vertical=v;return this;}public AbilityBuilder targets(boolean e,boolean p){entities=e;players=p;return this;}public AbilityBuilder projectile(double speed,double maxRange,int lifetime){projectile=new AbilityDefinition.ProjectileSpec(speed,maxRange,lifetime,true);return this;}public AbilityBuilder destruction(double radius,float strength,int maxBlocks){blocks=BlockInteraction.BREAK;destruction=new AbilityDefinition.DestructionSpec(radius,strength,maxBlocks);return this;}public AbilityDefinition build(){return new AbilityDefinition(id,name,description,cooldown,damage,range,area,duration,types,shape,effects,particle,sound,blocks,horizontal,vertical,entities,players,projectile,destruction);}}
